# >>> CHOICES
_choice_dynamic_store_key() {
    printf 'list\n' | scutil 2>/dev/null | sed -n 's/^  subKey \[[0-9]*\] = //p'
}

_choice_nc() {
    printf '%s\t%s\n' \
        list 'List available network connection services in the current set' \
        status 'Indicate whether a given service is connected, as well as extended status information for the service' \
        show 'Display configuration information for a given service' \
        statistics 'Provide statistics on bytes, packets, and errors for a given service' \
        select 'Make the given service active in the current set' \
        start 'Start a given service' \
        stop 'Stop a given service' \
        suspend 'Suspend a given service (PPP, Modem on Hold)' \
        resume 'Resume a given service (PPP, Modem on Hold)' \
        ondemand 'Display VPN on-demand information' \
        trigger 'Trigger VPN on-demand with specified hostname, and optional port and background flag' \
        enablevpn 'Enables the given VPN application type' \
        disablevpn 'Disables the given VPN application type' \
        help 'Display available commands for --nc'
}

_choice_renew() {
    ifconfig -l 2>/dev/null | tr ' ' '\n'
}

_choice_set() {
    if [[ ${#argc_set[@]} -eq 1 ]]; then
        printf '%s\t%s\n' \
            ComputerName 'The user-friendly name for the system' \
            LocalHostName 'The local (Bonjour) host name' \
            HostName 'The name associated with hostname(1) and gethostname(3)'
    fi
}
